// Collapse Split Out rows into one row of unique options
const rows = $input.all().map(i => i.json);

// helper: unique non-empty
const uniq = arr => [...new Set(arr.map(v => (v ?? '').toString().trim()).filter(Boolean))];

// pick columns (robust to slight header changes)
const getCol = (nameHints) => {
  const keys = Object.keys(rows[0] || {});
  const lcKeys = keys.map(k => k.toLowerCase());
  for (const hint of nameHints) {
    const idx = lcKeys.findIndex(k => k.includes(hint));
    if (idx !== -1) return keys[idx];
  }
  return null;
};

const colFunnel   = getCol(['funnel_stage','funnel stage','funnel']);
const colBlogType = getCol(['blog_type','blog type']);
const colBTCT     = getCol(['blog type - blog content type','blog content type','blog content']); 

// extract unique values
const funnelStages = uniq(rows.map(r => r[colFunnel]));
const blogTypes    = uniq(rows.map(r => r[colBlogType]));
const btctRaw      = uniq(rows.map(r => r[colBTCT]));

return [{
  json: {
    Funnel_Stage: funnelStages,                    // ["Awareness","Consideration","Decision","Retention"]
    Blog_Type: blogTypes,                          // ["Educational","Transactional","Proof-Based","Authority-Building"]
    "Blog Type - Blog Content Type": btctRaw       // full strings as in sheet (with descriptions)
  }
}];

// Inputs
const aiChoice = $json.output.blog_content_type.choice;  
// Example: "EDUCATIONAL + HOW-TO/TUTORIAL"

// Core selectors sheet rows (from previous node)
const rows = $items("Blog_Core_Selectors").map(i => i.json);

// Helper: case-insensitive match
function matchRow(aiChoice, rows) {
  const normalized = aiChoice.toLowerCase().trim();

  // Try exact match first
  let exact = rows.find(r => 
    (r["Blog Type - Blog Content Type"] || "").toLowerCase().trim() === normalized
  );
  if (exact) return exact;

  // If not found, try partial contains match
  let partial = rows.find(r => 
    (r["Blog Type - Blog Content Type"] || "").toLowerCase().includes(normalized)
  );
  if (partial) return partial;

  // If still not found, return null
  return null;
}

const matchedRow = matchRow(aiChoice, rows);

return [{
  json: {
    ai_choice: aiChoice,
    matched_row: matchedRow || "❌ No match found"
  }
}];

return items.map(item => {
  return {
    json: {
      topic: item.json["output.topic"],
      search_intent: item.json["output.search_intent"],
      funnel_stage: item.json["output.funnel_stage.choice"],
      blog_type: item.json["output.blog_type.choice"],
      content_depth: item.json["output.content_depth.choice"],
      blog_type_content: item.json["matched_row['Blog Type - Blog Content Type']"],
      blog_flow: item.json["matched_row['Blog Flow']"]
    }
  };
});

