const skeleton = items.map(item => {
  const s = item.json["output.skeleton"];
  return {
    section: s.section,
    intent: s.intent,
    influence_principle: s.influence_principle,
    emotional_arc: s.emotional_arc,
    transition: s.transition
  };
});

// Take the first item to keep shared metadata (topic, search_intent, etc.)
const first = items[0].json;

return [
  {
    json: {
      topic: first["output.topic"],
      search_intent: first["output.search_intent"],
      blog_type_content: first["output.blog_type_content"],
      blog_flow: first["output.blog_flow"],
      content_depth: first["output.content_depth"],
      hook_type: first["output.hook_type"],
      cta: first["output.cta"],
      closing_style: first["output.closing_style"],
      primary_keyword: first["primary_keyword"],
      main_keywords: first["main_keywords"],
      long_tail_keywords: first["long_tail_keywords"],
      nlp_keywords: first["nlp_keywords"],
      semantic_keywords: first["semantic_keywords"],
      faqs: first["faqs"],
      skeleton
    }
  }
];

// Normalize & output with clean headers

return items.map(item => {
  const j = item.json;

  const pick = (obj, keys) => {
    for (const k of keys) {
      if (Object.prototype.hasOwnProperty.call(obj, k) && obj[k] != null && obj[k] !== '') {
        return obj[k];
      }
    }
    return '';
  };

  const norm = v => Array.isArray(v) ? v.join(', ') : (v ?? '');

  return {
    json: {
      topic: norm(pick(j, ['topic', 'output.topic'])),
      search_intent: norm(pick(j, ['search_intent', 'output.search_intent'])),
      blog_type_content: norm(pick(j, ['blog_type_content', 'output.blog_type_content'])),
      blog_flow: norm(pick(j, ['blog_flow', 'output.blog_flow'])),
      content_depth: norm(pick(j, ['content_depth', 'output.content_depth'])),
      skeleton: pick(j, ['skeleton', 'output.skeleton']) ?? [],

      // Clean header names
      primary_keyword: norm(pick(j, ["['primary keyword']", 'primary_keyword', 'primary keyword'])),
      main_keywords: norm(pick(j, ["['main keywords']", 'main_keywords', 'main keywords'])),
      long_tail_keywords: norm(pick(j, ["['long tail keywords']", 'long_tail_keywords', 'long tail keywords'])),
      nlp_keywords: norm(pick(j, ["['nlp keywords']", 'nlp_keywords', 'nlp keywords'])),
      faqs: norm(pick(j, ['faqs', 'FAQs', 'output.faqs'])),
      semantic_keywords: norm(pick(j, ["['semantic keywords']", 'semantic_keywords', 'semantic keywords'])),
    }
  };
});

