// Helper: get first non-space char index going forward from i
function nextSignificantChar(str, i) {
  for (let k = i; k < str.length; k++) {
    const c = str[k];
    if (!/\s/.test(c)) return c;
  }
  return '';
}

// Repair inner (unescaped) quotes inside JSON string values.
// Strategy: scan once; when inside a *value* string, escape any " that
// is NOT the terminating quote (i.e., the next non-space char after it
// is NOT , ] or } ), unless it's already escaped.
function repairInnerQuotes(jsonText) {
  let out = '';
  let i = 0;
  const n = jsonText.length;

  let inString = false;        // currently inside any "... "
  let stringIsValue = false;   // true only when inside a VALUE string (not a key)
  let escaped = false;         // last char was backslash
  let justClosedKey = false;   // we just closed a key and expect ':' next

  // A quick state to detect keys: previous non-space before opening " is { or ,
  function isKeyStart(str, pos) {
    for (let k = pos - 1; k >= 0; k--) {
      const c = str[k];
      if (/\s/.test(c)) continue;
      return (c === '{' || c === ',');
    }
    return false;
  }

  while (i < n) {
    const ch = jsonText[i];

    if (!inString) {
      // Outside any string
      if (ch === '"') {
        inString = true;
        escaped = false;

        // Determine if this string is a KEY or a VALUE
        const keyLike = isKeyStart(jsonText, i);
        stringIsValue = !keyLike; // if not key-like, treat as value string
        out += ch;
      } else {
        out += ch;
      }
      i++;
      continue;
    }

    // Inside a string
    if (escaped) {
      out += ch;
      escaped = false;
      i++;
      continue;
    }

    if (ch === '\\') {
      out += ch;
      escaped = true;
      i++;
      continue;
    }

    if (ch === '"') {
      // Potentially closing quote of current string…
      const nextSig = nextSignificantChar(jsonText, i + 1);
      const looksLikeTerminator = (nextSig === ',' || nextSig === '}' || nextSig === ']');

      if (stringIsValue && !looksLikeTerminator) {
        // It's an INNER quote inside a value → escape it
        out += '\\"';
        i++;
        continue;
      } else {
        // It closes the string
        inString = false;
        stringIsValue = false;
        out += ch;
        i++;
        continue;
      }
    }

    out += ch;
    i++;
  }

  return out;
}

// --- MAIN ---

// accept either { output: "..."} or [{ output: "..." }] or object already
let raw = $json.output ?? ($json[0]?.output ?? $json);

// Case: already an object (model sometimes returns parsed object)
if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
  return raw;
}

// Case: LLM wrapped JSON in a markdown code fence string
if (typeof raw === 'string') {
  let clean = raw
    .replace(/^\s*```json\s*/i, '')
    .replace(/^\s*```\s*/i, '')
    .replace(/\s*```$/i, '')
    // strip zero-width & odd control chars that sneak in
    .replace(/[\u200B-\u200D\uFEFF]/g, '');

  // Try a normal parse first
  try {
    return JSON.parse(clean);
  } catch (e1) {
    // Repair inner quotes inside value strings, then parse
    const repaired = repairInnerQuotes(clean);
    try {
      return JSON.parse(repaired);
    } catch (e2) {
      throw new Error(
        "JSON.parse failed even after repair:\n" +
        e2.message + "\n\nFirst 400 chars of repaired text:\n" +
        repaired.slice(0, 400)
      );
    }
  }
}

throw new Error("No valid output found: expected an object or a JSON string.");

function transformContent(node) {
  if (Array.isArray(node)) return node.map(transformContent);

  if (typeof node === "object" && node !== null) {
    let out = { ...node };

    switch (out.type) {
      case "heading":
        out.text = "<<< placeholder: heading text >>>";
        break;

      case "paragraph":
        out.text = "<<< placeholder: paragraph text >>>";
        break;

      case "callout":
        out.text = "<<< placeholder: callout message >>>";
        break;

      case "image":
        out.src = "<<< placeholder: /images/path.png >>>";
        out.alt = "<<< placeholder: alt description >>>";
        out.caption = "<<< placeholder: image caption >>>";
        break;

      case "code":
        out.language = out.language || "json";
        out.code = "<<< placeholder: code snippet >>>";
        break;

      case "quote":
        out.text = "<<< placeholder: quote text >>>";
        out.cite = "<<< placeholder: citation/source >>>";
        break;

      // ✅ Dynamic List
      case "list":
        out.items = [
          "<<< placeholder: list item text >>>",
          {
            placeholder: "<<< dynamic: list items to be generated by content agent (any number allowed) >>>"
          }
        ];
        break;

      // ✅ Dynamic FeaturesGrid / IconBar
      case "featuresGrid":
      case "iconBar":
        out.items = [
          {
            icon: "<<< placeholder: icon type (from schema) >>>",
            title: `<<< placeholder: ${out.type} title >>>`,
            text: `<<< placeholder: ${out.type} text >>>`
          },
          {
            placeholder: `<<< dynamic: ${out.type} items to be generated by content agent (any number allowed) >>>`
          }
        ];
        break;

      // ✅ Dynamic StatsList
      case "statsList":
        out.heading = "<<< placeholder: stats heading >>>";
        out.caption = "<<< placeholder: stats caption >>>";
        out.items = [
          {
            value: "<<< placeholder: metric value >>>",
            text: "<<< placeholder: metric text >>>"
          },
          {
            placeholder: "<<< dynamic: statsList items to be generated by content agent (any number allowed) >>>"
          }
        ];
        break;

      case "divider":
        // divider has no fields
        break;

      default:
        // fallback for unknown or nested objects
        for (const k of Object.keys(out)) {
          out[k] = transformContent(out[k]);
        }
    }

    return out;
  }

  return node;
}

// --- MAIN WRAPPER ---
function transformSkeleton(json) {
  if (Array.isArray(json)) return json.map(transformSkeleton);
  if (typeof json === "object" && json !== null) {
    let out = { ...json };

    if (out.content_structure) {
      out.content_structure = out.content_structure.map(transformContent);
    }
    // recurse for nested structures
    for (const k of Object.keys(out)) {
      if (typeof out[k] === "object") {
        out[k] = transformSkeleton(out[k]);
      }
    }
    return out;
  }
  return json;
}

let raw = $json.output ?? ($json[0]?.output ?? $json);
if (typeof raw === "string") raw = JSON.parse(raw);

return transformSkeleton(raw);

// Get raw output from previous agent
