// Parse if it's a string
if (typeof raw === "string") {
  try {
    raw = JSON.parse(raw);
  } catch (e) {
    raw = { error: "Invalid JSON string from previous step", raw };
  }
}

// Wrap everything under one top-level field
return {
  blog_blueprint: raw
};

