// Step 1 — Ensure it's a string
if (typeof raw !== "string") {
  throw new Error("Expected stringified JSON with ```json fencing, got object");
}

// Step 2 — Extract only the JSON block between ```json and ```
let match = raw.match(/```json([\s\S]*?)```/);

if (!match) {
  throw new Error("No ```json block found in output:\n" + raw.slice(0, 200));
}

let cleaned = match[1].trim();

// Step 3 — Parse into object
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Failed to parse JSON: " + e.message + "\nCleaned string:\n" + cleaned);
}

// Step 4 — Return clean JSON (ready for publishing)
return [parsed];

